import { useEffect } from "react";
import { type Locale, getLocale, setLocale as runtimeSetLocale } from "./runtime";

const RTL_LOCALES = new Set<Locale>(["ar-AE"]);

export function isRtlLocale(locale: Locale): boolean {
  return RTL_LOCALES.has(locale);
}

function applyDirection(locale: Locale): void {
  document.documentElement.dir = isRtlLocale(locale) ? "rtl" : "ltr";
}

export function useLocaleDirection(): "ltr" | "rtl" {
  const locale = getLocale();
  const dir = isRtlLocale(locale) ? "rtl" : "ltr";

  useEffect(() => {
    applyDirection(locale);
  }, [locale]);

  return dir;
}

export { runtimeSetLocale as setLocale };


