/**
 * Unified i18n route manifest.
 *
 * Every route exercised by the pseudolocale gate must have an entry here.
 * The pseudolocale spec (i18n-pseudolocale.spec.ts) drives its test loop
 * from this array — adding a route to an MFE without registering it here
 * will fail the parity vitest in E3/E5/E6, not just the spec.
 *
 * Field notes:
 *   path          — Exact URL path navigated in the test. For popover tests
 *                   that open on top of an existing page, this is the base
 *                   page path (e.g. "/" for dashboard popovers).
 *   mfe           — Which MFE owns this route:
 *                     "shell"     → shell-mfe (paths: /login, /, /profile, etc.)
 *                     "admin"     → admin-mfe (paths: /admin/*)
 *                     "files" → files-mfe (paths: /files/*)
 *                     "dialogue"  → dialogue-mfe (paths: /dialogue/*)
 *   authStubbed   — true when the test stubs /api/v1/session so RequireAuth
 *                   doesn't redirect to /login (all auth-gated pages).
 *                   false only for the /login page itself.
 *   popoverTrigger — testId of the topbar element clicked to open the popover,
 *                   present only for the 4 topbar popover tests.
 *
 * Seeded with the 13 routes from i18n-pseudolocale.spec.ts at time of manifest
 * creation. E3/E5/E6 will expand this to ~26 entries covering all MFE routes.
 */

export type I18nGatedRoute = {
  /** URL path navigated during the test. */
  path: string;
  /** Which MFE owns this route. */
  mfe: "shell" | "admin" | "files" | "dialogue" | "range";
  /** Whether the test stubs /api/v1/session via page.route(). */
  authStubbed: boolean;
  /**
   * For topbar-popover tests: the data-testid of the trigger button.
   * When present the spec opens this element before collecting violations.
   */
  popoverTrigger?: string;
  /**
   * For in-page modal tests: the data-testid of the button that opens the
   * modal. When present the spec navigates to path, waits for the trigger
   * to be visible, clicks it, waits for role="dialog", then checks violations.
   */
  modalTrigger?: string;
  /**
   * Human-readable label used in test titles and violation reports.
   * Falls back to path when absent.
   */
  label?: string;
};

export const I18N_GATED_ROUTES: readonly I18nGatedRoute[] = [
  // ── shell-mfe routes ───────────────────────────────────────────────────────

  {
    // LoginRoute — LocaleSwitcher (popover variant) is mounted here.
    // No session required; the entire page renders unauthenticated.
    path: "/login",
    mfe: "shell",
    authStubbed: false,
    label: "/login",
  },
  {
    // Dashboard (HomeGreeting, StatTiles, QuickActionCards).
    // Session is stubbed so RequireAuth grants access without Keycloak.
    path: "/",
    mfe: "shell",
    authStubbed: true,
    label: "/ (dashboard)",
  },
  {
    // Topbar notifications popover — only in the DOM after clicking the bell.
    // Opens on top of the dashboard; path is "/" (base page).
    path: "/",
    mfe: "shell",
    authStubbed: true,
    popoverTrigger: "topbar-notifications-trigger",
    label: "topbar notifications popover",
  },
  {
    // Topbar user menu popover — opens on top of the dashboard.
    path: "/",
    mfe: "shell",
    authStubbed: true,
    popoverTrigger: "topbar-user-menu-trigger",
    label: "topbar user menu popover",
  },
  {
    // Topbar nav menu — opens on top of the dashboard.
    path: "/",
    mfe: "shell",
    authStubbed: true,
    popoverTrigger: "topbar-nav-trigger",
    label: "topbar nav menu popover",
  },

  {
    // ProfileRoute — read-only profile card.
    path: "/profile",
    mfe: "shell",
    authStubbed: true,
    label: "/profile",
  },
  {
    // AccountRoute — three section card scaffold (Security, Preferences, Notifications).
    path: "/account",
    mfe: "shell",
    authStubbed: true,
    label: "/account",
