  // ── files-mfe routes ───────────────────────────────────────────────────

  {
    // CorpusList — default knowledge route. Stubs corpora list to empty state.
    path: "/files",
    mfe: "files",
    authStubbed: true,
    label: "/files",
  },
  {
    // CorpusCreate — new corpus form.
    path: "/files/new",
    mfe: "files",
    authStubbed: true,
    label: "/files/new",
  },
  {
    // CorpusDetail — parametric. Fixture UUID 00000000-…-0010 is the
    // CORPUS_FIXTURE_ID constant in the E6 parity vitest and is already used
    // for the modal-trigger entries below, so the parity check resolves
    // /files/corpora/:id → this path.
    path: "/files/corpora/00000000-0000-0000-0000-000000000010",
