/**
 * localeForIntl — maps the platform's active Locale to an Intl-compatible BCP
 * 47 tag. The only special case is `xx-pseudo`: it is a dev-only sentinel that
 * has no corresponding on-disk message files; for Intl purposes we fold it to
 * `en-US` so formatters produce legible output in pseudo-locale mode.
 *
 * Mirrors the `xx-pseudo → "en-US"` trick already used in runtime.ts for the
 * Paraglide locale mapping.
 */

import { type Locale, PSEUDO_LOCALE } from "./runtime";

export function localeForIntl(locale: Locale): string {
  return locale === PSEUDO_LOCALE ? "en-US" : locale;
}


--- frontends/platform-chrome/src/i18n/pseudolocale.ts (223 lines) ---
/**
 * pseudolocale.ts — runtime pseudolocale transform for xx-pseudo.
 *
 * Transforms an en-US string so that every untranslated string is visually
 * obvious in dev: letters get diacritics, the string is wrapped in [!! !!],
 * but ICU placeholders, glossary terms, and HTML entities are preserved
 * byte-exact.
 *
 * Usage:
 *   import { pseudolocalize } from "./pseudolocale";
 *   pseudolocalize("Sign in")  // "[!! Šïgñ ïñ !!]"
 */

// ── Glossary terms ────────────────────────────────────────────────────────────
//
// The UI-label subset of scripts/i18n-audit.ts GLOSSARY_TERMS: terms that
// surface as a standalone label, so a text node can equal one exactly. Must
// stay in lockstep with leakObserver.ts GLOSSARY_TERMS — a term preserved here
// but not allowlisted there reads as a leak.
//
// The audit list is deliberately WIDER: Reddit, YouTube, Kite, Porch, Commons,
// Courier, and Frame are content-domain names that appear inside body copy
// rather than as labels of their own. Preserving those here would only shrink
// leak coverage (an untranslated occurrence would stop being pseudo-ized)
// without buying an allowlist hit, since the allowlist matches whole nodes.
const GLOSSARY_TERMS: readonly string[] = [
  "OmniCore",
  "Canvas",
  "Studio",
  "Amplify",
  "Range",
  "Ask",
  "Workflows",
  "Dialogue",
  "Queue",
  "Spaces",
  "Rooms",
  "Documents",
  "Agents",
  "Chat",
  "Character",
  "Campaign",
  "API",
  "URL",
  "JSON",
  "CSV",
  "ID",
];

// ── Diacritic map ─────────────────────────────────────────────────────────────
// Vowels + a handful of consonants for variety.
const DIACRITIC_MAP: Readonly<Record<string, string>> = {
  a: "ä",
  A: "Ä",
  e: "ë",
  E: "Ë",
  i: "ï",
  I: "Ï",
  o: "ö",
  O: "Ö",
  u: "ü",
  U: "Ü",
  c: "ç",
  C: "Ç",
  n: "ñ",
  N: "Ñ",
  s: "š",
  S: "Š",
};

function diacritify(ch: string): string {
  return DIACRITIC_MAP[ch] ?? ch;
}

// ── Token types ───────────────────────────────────────────────────────────────
// We split the input into tokens: PROTECT (pass through) | TEXT (transform).
type Token =
  | { kind: "protect"; value: string }
  | { kind: "text"; value: string };

function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Build a regex that matches simple ICU placeholders `{word}`, HTML entities,
 * and glossary terms. Complex ICU plurals with nested braces are handled by a
 * separate brace-balanced extractor that runs first during tokenization.
 */
function buildProtectPattern(): RegExp {
  // Simple placeholder: {word}  (no comma inside)
  const icuSimple = String.raw`\{[a-zA-Z_][a-zA-Z0-9_]*\}`;
  // HTML entity: &word; or &#digits; or &#xHEX;
  const entity = String.raw`&(?:#\d+|#x[0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);`;
  // Glossary terms: longest first so "OmniCore" beats "Core"
  const sortedTerms = [...GLOSSARY_TERMS].sort((a, b) => b.length - a.length);
  const glossary = sortedTerms.map((t) => escapeRegex(t)).join("|");

  const pattern = [icuSimple, entity, glossary].join("|");
  return new RegExp(`(${pattern})`, "g");
}

const PROTECT_PATTERN = buildProtectPattern();

/**
 * Extract one brace-balanced ICU complex placeholder starting at `pos` in
 * `input`. Returns [matchedString, endPos] or null if the brace at `pos` does
 * not contain a comma (i.e., is a simple placeholder handled by the regex).
 *
 * We need this because regex cannot handle nested `{…}` groups (the
 * `{count, plural, one {# item} other {# items}}` pattern has depth-2 braces).
 */
function extractIcuComplex(
  input: string,
  pos: number,
): [string, number] | null {
  if (input[pos] !== "{") return null;
  // Scan to find the matching closing brace using a depth counter.
  let depth = 0;
  let i = pos;
  while (i < input.length) {
    if (input[i] === "{") depth++;
    else if (input[i] === "}") {
      depth--;
      if (depth === 0) {
        const candidate = input.slice(pos, i + 1);
        // Only treat as "complex" (protect) if it has a comma after the key name
        // pattern `{word,` — simple `{word}` is handled by the regex.
        if (/^\{[a-zA-Z_][a-zA-Z0-9_]*,/.test(candidate)) {
          return [candidate, i + 1];
        }
        // It's a simple placeholder — let the regex handle it.
        return null;
      }
    }
    i++;
  }
  return null;
}

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0;

  while (pos < input.length) {
    // 1. Try brace-balanced ICU complex placeholder at current position.
    if (input[pos] === "{") {
      const complex = extractIcuComplex(input, pos);
      if (complex !== null) {
        const [matched, end] = complex;
        tokens.push({ kind: "protect", value: matched });
        pos = end;
        continue;
      }
    }

    // 2. Run the simple-patterns regex from the current pos onwards.
    //    We need to find the NEAREST match at or after pos.
    PROTECT_PATTERN.lastIndex = pos;
    const match = PROTECT_PATTERN.exec(input);

    if (match !== null && match.index === pos) {
      // Pattern starts right here — consume it as a protected token.
      tokens.push({ kind: "protect", value: match[0] });
      pos = match.index + match[0].length;
    } else {
      // No pattern at current pos. Emit text up to the next candidate
      // position (next `{`, next `&`, or end of string — whichever comes first,
      // and also the next regex match if one exists). When the current char
      // itself looks like a protect-candidate boundary (e.g., a bare `&` that
      // doesn't form a valid HTML entity, or a `{` that isn't a recognized
      // ICU shape) the candidate positions equal `pos`, so we MUST advance
      // by at least one character — otherwise the loop never progresses and
      // the browser freezes (regression: "Manage password & 2FA" type
      // strings dragging in an unescaped `&` infinite-looped here).
      const nextBrace = input.indexOf("{", pos + 1);
      const nextAmp = input.indexOf("&", pos + 1);
      const nextRegex = match !== null ? match.index : input.length;

      const candidates = [
        nextBrace >= 0 ? nextBrace : input.length,
        nextAmp >= 0 ? nextAmp : input.length,
        nextRegex,
      ];
      let stop = Math.min(...candidates);
      if (stop <= pos) {
        // Defensive belt-and-braces: even with `pos + 1` above, an empty
        // string from regex.exec with lastIndex at end could surface a
        // stop <= pos. Force progress.
        stop = pos + 1;
      }
      tokens.push({ kind: "text", value: input.slice(pos, stop) });
      pos = stop;
    }
  }

  return tokens;
}

/**
 * Transform a plain text segment: apply diacritics character-by-character.
 */
function transformText(text: string): string {
  return Array.from(text)
    .map((ch) => diacritify(ch))
    .join("");
}

/**
 * pseudolocalize — the main export.
 *
 * @param str - An en-US message string (may contain ICU placeholders and
 *   glossary terms). May be empty.
 * @returns The pseudolocalized string wrapped with `[!! ` … ` !!]`.
 */
export function pseudolocalize(str: string): string {
  const tokens = tokenize(str);
  const body = tokens
    .map((t) => (t.kind === "protect" ? t.value : transformText(t.value)))
    .join("");
  return `[!! ${body} !!]`;
}


