/**
 * useFormatDate — returns a memoized Intl.DateTimeFormat instance keyed on the
 * active locale and the provided options.
 *
 * The hook subscribes to the platform's active locale via useLocale() so the
 * formatter is recreated automatically when the user switches languages.
 *
 * Memo key: (locale, JSON.stringify(opts)) — stable for structurally identical
 * options objects regardless of reference identity.
 *
 * xx-pseudo locale is folded to en-US via localeForIntl() so pseudo-locale
 * mode still produces legible formatted output.
 *
 * Usage:
 *   const fmt = useFormatDate({ dateStyle: "short" });
 *   return <time>{fmt.format(date)}</time>;
 */

import { useMemo } from "react";
import { useLocale } from "./runtime";
import { localeForIntl } from "./localeForIntl";

export function useFormatDate(
  opts?: Intl.DateTimeFormatOptions,
): Intl.DateTimeFormat {
  const { locale } = useLocale();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return useMemo(
    () => new Intl.DateTimeFormat(localeForIntl(locale), opts),
    // JSON.stringify provides stable serialization for structurally identical
    // option objects passed as new literals on each render (Step A3).
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [locale, JSON.stringify(opts)],
  );
}


