/**
 * Dev-only MutationObserver hook that warns when raw (un-translated) text
 * reaches the DOM.
 *
 * All logic is gated behind import.meta.env.DEV — production bundles get
 * zero overhead (dead-code eliminated by the bundler).
 *
 * ## How it works
 * 1. On mount, scan the existing DOM for text nodes.
 * 2. Set up a MutationObserver to catch text nodes added after mount.
 * 3. For each text node: run allowlist filters; if none match and the string
 *    is not in the translation registry, fire console.warn.
 * 4. Disconnect the observer on unmount.
 *
 * ## Opt-out for legitimate dynamic content
 * Wrap elements that display user-entered data with `data-i18n-allow="data"`:
 *   <span data-i18n-allow="data">{workspaceName}</span>
 *
 * ## Composition note
 * isTranslated() reads from the same Set that tag() populates in registry.ts.
 * For this to work correctly, m.*() functions must be wrapped with tag() (or
 * wrapForDev()) in messages.ts before they are called at render time.
 */

import { useEffect } from "react";
import { isTranslated } from "./registry";

// ─── Glossary — brand / product terms that are never translated ───────────────

/**
 * The UI-label glossary subset — mirrors pseudolocale.ts GLOSSARY_TERMS exactly
 * and must stay in lockstep with it: a term preserved there but missing here
 * reads as a leak. See that file for why the audit's list is wider.
 *
 * "CognitiveOS" is here but NOT in scripts/i18n-audit.ts, and that is correct:
 * the audit only inspects message-catalog values, while the wordmark is
 * hardcoded JSX (Topbar.tsx). Without this entry the gate flags the wordmark.
 */
export const GLOSSARY_TERMS: ReadonlySet<string> = new Set([
  "OmniCore",
  "CognitiveOS",
  "Canvas",
  "Studio",
  "Amplify",
  "Range",
  "Ask",
  "Workflows",
  "Dialogue",
  "Queue",
  "Spaces",
  "Rooms",
  "Documents",
  "Agents",
  "Chat",
  "Character",
  "Campaign",
  "API",
  "URL",
  "JSON",
  "CSV",
  "ID",
]);

// ─── Tag names to skip entirely ───────────────────────────────────────────────

/** Text inside these elements is data/code, not UI labels. */
const SKIP_TAG_NAMES: ReadonlySet<string> = new Set([
  "SCRIPT",
  "STYLE",
  "CODE",
  "PRE",
  "KBD",
  "SAMP",
  "VAR",
  "INPUT",
  "TEXTAREA",
  "SELECT",
  "OPTION",
]);

// ─── Patterns that are definitely not translatable UI text ───────────────────

/** Numbers, dates, times, punctuation-only, currency amounts, percentages. */
const NUMERIC_OR_SYMBOL_RE = /^[\d\s.,:%/\-+()[\]{}*#@$€£¥|~^_]+$/;
/** No Latin/CJK/Arabic/Cyrillic letters at all — definitely not a label. */
const NO_LETTER_RE = /^[^\p{L}]+$/u;
/** Email addresses. */
const EMAIL_RE = /^[\w.+%-]+@[\w-]+\.[\w.-]+$/;
/** URLs. */
const URL_RE = /^https?:\/\//;
/** UUIDs / hex IDs — common in data columns. */
const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// ─── Core check logic ─────────────────────────────────────────────────────────

/**
 * Build a compact, bounded one-line locator for the offending element.
 *
 * We deliberately do NOT hand the live DOM node to console.warn: a jsdom
 * element carries React's `__reactFiber$…` / `__reactProps$…` expandos, whose
 * `return`/`child`/`sibling`/`alternate` pointers form a cycle through the
 * entire fiber tree. When this runs under Vitest's forked-worker pool, every
 * such warning is serialized over worker→main IPC, ballooning a single leak
 * into megabytes of circular-graph output — enough to flood CI logs and
 * starve a worker into "Worker exited unexpectedly". A short `<tag id class>`
 * string is all that's diagnostically useful and is cheap to serialize.
 */
function describeElement(el: Element | null): string {
  if (el === null) return "<unknown>";
  const tag = el.tagName.toLowerCase();
  const id = el.id ? `#${el.id}` : "";
  const cls =
    typeof el.className === "string" && el.className.trim().length > 0
      ? `.${el.className.trim().split(/\s+/).slice(0, 4).join(".")}`
      : "";
  return `<${tag}${id}${cls}>`;
}

/**
 * Checks a single text node's content against the allowlist. Fires
 * console.warn if the text looks like an untranslated UI label.
 *
 * @param raw  - raw textContent of the text node
 * @param el   - nearest parent Element (for context in the warning)
 */
function checkText(raw: string, el: Element | null): void {
  const trimmed = raw.trim();

  // Too short to be a meaningful label
  if (trimmed.length < 2) return;

  // Skip numeric/symbol-only strings (prices, counts, dates)
  if (NUMERIC_OR_SYMBOL_RE.test(trimmed)) return;

  // Skip if there are no letters at all (pure punctuation, arrows, etc.)
  if (NO_LETTER_RE.test(trimmed)) return;

  // Skip emails and URLs
  if (EMAIL_RE.test(trimmed)) return;
  if (URL_RE.test(trimmed)) return;

  // Skip UUIDs / hex IDs
  if (UUID_RE.test(trimmed)) return;

  // Skip glossary brand terms that appear standalone
  if (GLOSSARY_TERMS.has(trimmed)) return;

  // Skip text inside code/input/pre/etc. elements
  if (el !== null) {
    // Check the direct parent tag
    if (SKIP_TAG_NAMES.has(el.tagName)) return;
    // Check any ancestor up the tree
    if (el.closest("code, pre, kbd, samp, var, input, textarea, select")) {
      return;
    }
    // Skip elements whose closest ancestor has the opt-out attribute
    if (el.closest('[data-i18n-allow="data"]') !== null) return;
  }

  // Came from a m.*() call — legitimately translated
  if (isTranslated(trimmed)) return;

  console.warn(
    `[i18n-leak] Untranslated text in DOM: ${JSON.stringify(trimmed.slice(0, 80))}`,
    describeElement(el),
  );
}

/**
 * Walk all text-node children of an element and check each one.
 */
function scanElement(el: Element): void {
  for (const child of el.childNodes) {
    if (child.nodeType === Node.TEXT_NODE && child.textContent !== null) {
      checkText(child.textContent, el);
    }
  }
}

/**
 * Handle a newly added DOM node (called from MutationObserver).
 */
function handleAddedNode(node: Node): void {
  if (node.nodeType === Node.TEXT_NODE) {
    if (node.textContent !== null) {
      checkText(node.textContent, node.parentElement);
    }
    return;
  }

  if (node.nodeType === Node.ELEMENT_NODE) {
    const el = node as Element;
    scanElement(el);
    // Also walk descendants
    for (const descendant of el.querySelectorAll("*")) {
      scanElement(descendant);
    }
  }
}

// ─── React hook ───────────────────────────────────────────────────────────────

/**
 * Mount this once inside I18nProvider. In DEV mode it:
 * 1. Scans the current DOM for un-translated text.
 * 2. Observes future mutations via MutationObserver.
 * 3. Disconnects cleanly on unmount.
 *
 * In production this hook is a no-op (empty useEffect returning undefined).
 */
export function useTranslationLeakObserver(): void {
  useEffect(() => {
    if (!import.meta.env.DEV) return;
    // In e2e builds (VITE_E2E=1) the MutationObserver is disabled to prevent
    // the observer callback from blocking the browser event loop during
    // Playwright test execution. Pseudolocale checking is handled by the
    // spec-side collectViolations() DOM walker instead.
    if (import.meta.env.VITE_E2E === "1") return;

    // Initial DOM scan
    for (const el of document.body.querySelectorAll("*")) {
      scanElement(el);
    }

    // Ongoing observation
    const observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        if (mutation.type === "characterData") {
          if (mutation.target.textContent !== null) {
            checkText(
              mutation.target.textContent,
              mutation.target.parentElement,
            );
          }
          continue;
        }
        for (const node of mutation.addedNodes) {
          handleAddedNode(node);
        }
      }
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: true,
    });

    return () => {
      observer.disconnect();
    };
  }, []);
}


