/**
 * Dev-mode translation registry.
 *
 * Records every string produced by m.*() calls so the leak observer can
 * distinguish "came from a translator" vs raw hardcoded text.
 *
 * ## Composition with pseudolocale-builder
 * When both this module and pseudolocalize.ts are active, the composition
 * order in messages.ts should be:
 *
 *   export const foo = tag(withPseudoTransform(_foo));
 *
 * i.e. pseudo first, then tag — so the already-pseudo-localized string is
 * what gets recorded in the registry. That way isTranslated() still returns
 * true even in xx-pseudo locale mode.
 *
 * Both agents wrap via wrapForDev() in this file. The pseudolocale agent
 * extends wrapForDev() with its own transform when it lands. See the
 * "// dev instrumentation" section in messages.ts.
 *
 * All exports are gated behind import.meta.env.DEV — zero overhead in prod.
 */

// ─── Internal registry ───────────────────────────────────────────────────────

/**
 * Set of every string ever returned by a tag()-wrapped function.
 *
 * Stored as a globalThis singleton so the registry is shared across
 * Module Federation boundaries. Each federated MFE bundles its own copy of
 * platform-chrome, but globalThis is shared — so strings recorded by
 * files-mfe's m.*() calls are visible to shell-mfe's leak observer.
 */
const REGISTRY_KEY = "__omnicore_i18n_translated__";
type GlobalWithRegistry = typeof globalThis & {
  [REGISTRY_KEY]?: Set<string>;
};
const __global__ = globalThis as GlobalWithRegistry;
if (__global__[REGISTRY_KEY] === undefined) {
  __global__[REGISTRY_KEY] = new Set<string>();
}
const __TRANSLATED__: Set<string> = __global__[REGISTRY_KEY];

// ─── Public API ──────────────────────────────────────────────────────────────

import { type TranslatedString } from "./translatedString";

/**
 * Wraps a Paraglide message function so every string it returns is recorded
 * in the registry AND branded as TranslatedString.
 *
 * The return type is widened from `F` to `(...args: Parameters<F>) => TranslatedString`
 * so that every `m.*()` call site is directly assignable to a
 * `TranslatedString`-typed prop without any explicit cast.
 *
 * In production (import.meta.env.DEV === false) returns the original function
 * with the same brand widening — zero runtime cost beyond the type.
 *
 * Usage in messages.ts:
 *   export const auth_signin_btn = tag(_auth_signin_btn);
 */
export function tag<F extends (...args: never[]) => string>(
  fn: F,
): (...args: Parameters<F>) => TranslatedString {
  if (!import.meta.env.DEV) {
    return (...args: Parameters<F>): TranslatedString =>
      fn(...args) as TranslatedString;
  }
  return (...args: Parameters<F>): TranslatedString => {
    const result = fn(...args);
    __TRANSLATED__.add(result.trim());
    return result as TranslatedString;
  };
}

/**
 * Returns true if the given text was produced by a tag()-wrapped function
 * (i.e. came from m.*()). Whitespace is trimmed before the lookup.
 *
 * Used by the leak observer to avoid false-positive warnings on properly
 * translated strings.
 */
export function isTranslated(text: string): boolean {
  return __TRANSLATED__.has(text.trim());
}

/**
 * Shared dev wrapper: composes the pseudolocale transform with the leak-observer
 * registry, and brands the return value as TranslatedString.
 *
 * Composition order: pseudo first, then record in registry — so the
 * pseudo-localized string is what gets recorded (isTranslated works correctly
 * even in xx-pseudo locale mode).
 *
 *   wrapForDev(fn) semantically === tag(withPseudoTransform(fn))
 *
 * The composition is inlined here (rather than delegated) to avoid a TypeScript
 * variance issue: `tag`'s constraint `F extends (...args: never[]) => string`
 * conflicts with the `(...args: Parameters<F>) => TranslatedString` shape that
 * `withPseudoTransform` returns.
 *
 * messages.ts uses wrapForDev() at every export so both transforms compose
 * automatically. The return type is `(...args: Parameters<F>) => TranslatedString`
 * so that every `m.*()` call site is branded.
 */
export function wrapForDev<F extends (...args: never[]) => string>(
  fn: F,
): (...args: Parameters<F>) => TranslatedString {
  if (!import.meta.env.DEV) {
    // Prod: no-op wrapper, brand cast only
    return (...args: Parameters<F>): TranslatedString =>
      fn(...args) as TranslatedString;
  }
  return (...args: Parameters<F>): TranslatedString => {
    // 1. Pseudolocalize if the active locale is xx-pseudo
    const raw = fn(...args);
    const result =
      getLocale() === PSEUDO_LOCALE ? pseudolocalize(raw) : raw;
    // 2. Record the (possibly pseudo-localized) string in the registry
    __TRANSLATED__.add(result.trim());
    return result as TranslatedString;
  };
}

// ─── Pseudolocale transform ──────────────────────────────────────────────────

// Import lazily here to avoid a circular dependency: pseudolocale.ts is
// dependency-free; registry.ts only calls it when DEV is true.
// Note: this is a module-level import — Vite/TypeScript tree-shakes it in prod.
import { pseudolocalize } from "./pseudolocale";
import { getLocale, PSEUDO_LOCALE } from "./runtime";

/**
 * Wraps a Paraglide message function so that when the active locale is
 * `xx-pseudo`, the returned string is piped through `pseudolocalize()`.
 *
 * In production (import.meta.env.DEV === false) returns a wrapper with the
 * same TranslatedString brand but no transform overhead.
 *
 * The wrapped function preserves the original call signature exactly, including
 * all input parameters. Return type is widened to TranslatedString so that
 * `tag(withPseudoTransform(fn))` composes cleanly.
 */
export function withPseudoTransform<F extends (...args: never[]) => string>(
  fn: F,
): (...args: Parameters<F>) => TranslatedString {
  if (!import.meta.env.DEV) {
    return (...args: Parameters<F>): TranslatedString =>
      fn(...args) as TranslatedString;
  }
  return (...args: Parameters<F>): TranslatedString => {
    const result = fn(...args);
    return (
      getLocale() === PSEUDO_LOCALE ? pseudolocalize(result) : result
    ) as TranslatedString;
  };
}


