import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useState,
} from "react";
import { setLocale as paraglideSetLocale } from "../paraglide/generated/runtime.js";
// dev instrumentation — import is dead-code-eliminated in production bundles
import { useTranslationLeakObserver } from "./leakObserver";

const REAL_LOCALES = [
  "en-US",
  "en-GB",
  "en-AU",
  "ar-AE",
  "de-DE",
  "es-419",
  "fr-CA",
  "ja-JP",
  "mn-MN",
  "tl-PH",
  "zh-Hans",
] as const;

export type RealLocale = (typeof REAL_LOCALES)[number];

/**
 * xx-pseudo is a dev-only runtime locale. It has no on-disk message files and
 * is invisible to the audit script. When active, every `m.*()` return value is
 * piped through `pseudolocalize()` so untranslated strings are visually obvious
 * in the browser.
 *
 * Exposed only when import.meta.env.DEV is true — dead-code-eliminated in
 * production bundles.
 */
export const PSEUDO_LOCALE = "xx-pseudo" as const;
export type PseudoLocale = typeof PSEUDO_LOCALE;

export const AVAILABLE_LOCALES = import.meta.env.DEV
  ? ([...REAL_LOCALES, PSEUDO_LOCALE] as const)
  : (REAL_LOCALES as unknown as readonly [...typeof REAL_LOCALES]);

/**
 * Locale type includes `xx-pseudo` at the type level.
 *
 * At runtime `xx-pseudo` is only present in `AVAILABLE_LOCALES` when
 * `import.meta.env.DEV` is true — production bundles tree-shake it away.
 * Typed as a union here so that `setLocale("xx-pseudo")` is valid in dev
 * tooling without needing a cast.
 */
export type Locale = RealLocale | PseudoLocale;

const STORAGE_KEY = "omnicore.locale";
const DEFAULT_LOCALE: Locale = "en-US";

function isLocale(value: string): value is Locale {
  return (AVAILABLE_LOCALES as readonly string[]).includes(value);
}

/**
 * Map an OmniCore locale to the locale Paraglide understands.
 *
 * Paraglide only knows about the 11 real locales — xx-pseudo is our dev-only
 * synthetic locale and would cause paraglideSetLocale() to throw if passed
 * through directly. wrapForDev() in messages.ts checks getLocale() === xx-pseudo
 * separately and pipes the resolved English string through pseudolocalize(),
 * so we tell Paraglide to resolve against en-US whenever the active locale
 * is xx-pseudo.
 *
 * MUST be used at every paraglideSetLocale call site — boot, setLocale,
 * cross-MFE CustomEvent handler, cross-tab StorageEvent handler. Forgetting
 * any one of them strands localStorage with "xx-pseudo" and crashes every
 * subsequent page load.
 */
function toParaglideLocale(
  locale: Locale,
): Parameters<typeof paraglideSetLocale>[0] {
  const real = locale === PSEUDO_LOCALE ? "en-US" : locale;
  return real as Parameters<typeof paraglideSetLocale>[0];
}

function matchNavigatorLocale(navLang: string): Locale | null {
  if (isLocale(navLang)) return navLang;
  const prefix = navLang.split("-")[0];
  const prefixMatch = AVAILABLE_LOCALES.find((l) =>
    l.toLowerCase().startsWith(prefix.toLowerCase() + "-"),
  );
  return prefixMatch ?? null;
}

function detectLocale(): Locale {
  try {
    const params = new URLSearchParams(window.location.search);
    const urlLocale = params.get("locale");
    if (urlLocale !== null && isLocale(urlLocale)) return urlLocale;
  } catch {
    // SSR / non-browser
  }

  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored !== null && isLocale(stored)) return stored;
  } catch {
    // private browsing
  }

  try {
    const nav = navigator.language;
    if (nav) {
      const matched = matchNavigatorLocale(nav);
      if (matched !== null) return matched;
    }
  } catch {
    // non-browser
  }

  return DEFAULT_LOCALE;
}

type LocaleListener = (locale: Locale) => void;
const listeners = new Set<LocaleListener>();
let currentLocale: Locale = detectLocale();

// Prime Paraglide at module-init, BEFORE any component renders.
// Otherwise the first paint of any MFE bundle (esp. federated remotes
// like admin-mfe / files-mfe) shows Paraglide's baseLocale (en-US)
// regardless of localStorage. I18nProvider's useEffect primes too late —
// it fires AFTER first render, and if state already matches detectLocale's
// pick, no re-render happens, so the initial English paint sticks.
//
// When xx-pseudo is requested we tell Paraglide to use en-US so it resolves
// English strings; wrapForDev() in messages.ts pipes results through
// pseudolocalize() when getLocale() === "xx-pseudo".
try {
  paraglideSetLocale(toParaglideLocale(currentLocale), { reload: false });
} catch {
  // SSR / non-browser
}

export function getLocale(): Locale {
  return currentLocale;
}

export function setLocale(locale: Locale): void {
  currentLocale = locale;
  try {
    localStorage.setItem(STORAGE_KEY, locale);
  } catch {
    // private browsing
  }
  // xx-pseudo has no Paraglide locale — use en-US as the backing locale so
  // Paraglide resolves English strings that wrapForDev() can pseudo-ify.
  paraglideSetLocale(toParaglideLocale(locale), { reload: false });
  listeners.forEach((l) => l(locale));
  // Broadcast to all I18nProvider instances in the same tab (cross-MFE).
  // StorageEvent only fires in OTHER tabs; CustomEvent covers same-tab MFEs.
  try {
    window.dispatchEvent(
      new CustomEvent("omnicore-locale-change", { detail: { locale } }),
    );
  } catch {
    // non-browser / test environment
  }
}

function subscribeLocale(listener: LocaleListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

const LocaleContext = createContext<{
  locale: Locale;
  setLocale: (locale: Locale) => void;
}>({
  locale: DEFAULT_LOCALE,
  setLocale,
});

export function useLocale(): { locale: Locale; setLocale: (l: Locale) => void } {
  return useContext(LocaleContext);
}

interface I18nProviderProps {
  children: React.ReactNode;
}

export function I18nProvider({ children }: I18nProviderProps): React.ReactElement {
  const [locale, setLocaleState] = useState<Locale>(getLocale);

  // dev instrumentation: warn on raw text nodes that bypass m.*()
  // No-op in production (hook body is gated on import.meta.env.DEV).
  useTranslationLeakObserver();

  // Prime Paraglide with detectLocale()'s pick: Paraglide otherwise boots at
  // its baseLocale and would render en-US on first paint regardless of URL,
  // localStorage, or navigator.
  useEffect(() => {
    paraglideSetLocale(toParaglideLocale(getLocale()), {
      reload: false,
    });
  }, []);

  // Subscribe to in-process locale changes (same-instance setLocale calls).
  useEffect(() => {
    return subscribeLocale((next) => {
      setLocaleState(next);
    });
  }, []);

  // React to locale switches from OTHER MFE bundles in the same tab via the
  // custom event dispatched by setLocale() above. Each remote MFE has its own
  // Paraglide bundle, so we must update that bundle's active locale too.
  useEffect(() => {
    const onCustomEvent = (e: Event) => {
      const detail = (e as CustomEvent<{ locale: string }>).detail;
      if (isLocale(detail.locale) && detail.locale !== currentLocale) {
        currentLocale = detail.locale;
        paraglideSetLocale(toParaglideLocale(detail.locale), {
          reload: false,
        });
        setLocaleState(detail.locale);
      }
    };
    window.addEventListener("omnicore-locale-change", onCustomEvent);
    return () => window.removeEventListener("omnicore-locale-change", onCustomEvent);
  }, []);

  // React to locale switches from OTHER browser tabs (localStorage writes).
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY && e.newValue !== null && isLocale(e.newValue)) {
        currentLocale = e.newValue;
        paraglideSetLocale(toParaglideLocale(e.newValue), {
          reload: false,
        });
        setLocaleState(e.newValue);
      }
    };
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, []);

  const handleSetLocale = useCallback((next: Locale) => {
    setLocale(next);
  }, []);

  return React.createElement(
    LocaleContext.Provider,
    { value: { locale, setLocale: handleSetLocale } },
    children,
  );
}


