/**
 * TranslatedString — nominal brand type for strings that have passed through
 * the Paraglide message pipeline (tag() / wrapForDev()).
 *
 * Raw string literals CANNOT be assigned to TranslatedString without the
 * unsafeAsTranslated() escape hatch. This makes "passed a hardcoded string to a
 * translation-required prop" a compile-time error, not a runtime surprise.
 *
 * The brand is erased at runtime — TranslatedString IS a string at runtime.
 * It adds zero bytes to the production bundle.
 *
 * ## Usage
 *
 * In message-producing code (registry.ts):
 *   The return type of tag<F>() / wrapForDev<F>() / withPseudoTransform<F>()
 *   is widened to TranslatedString.
 *
 * In component props:
 *   Replace `label: string` with `label: TranslatedString` on user-visible
 *   text props. Call sites already passing m.*() values automatically satisfy
 *   the type (m.*() returns TranslatedString after registry.ts is retyped).
 *
 * In tests / escape hatches:
 *   Use unsafeAsTranslated() with an `// i18n-allow: <reason>` comment.
 *   Example:
 *     const heading = unsafeAsTranslated(dynamicValue); // i18n-allow: data from BFF
 */

// The `unique symbol` intersection ensures structural subtyping cannot satisfy
// the brand with a plain `string` — the only valid path is through the runtime
// cast in unsafeAsTranslated() or through the registry wrappers.
export type TranslatedString = string & { readonly __translated: unique symbol };

/**
 * Escape hatch: cast any string to TranslatedString.
 *
 * Every call site MUST include a same-line `// i18n-allow: <reason>` comment
 * explaining why the value doesn't need to go through the message catalog.
 * The C-audit step (Task 9) will review every call site before merge.
 *
 * @example
 *   // Dynamic data from the BFF — not a translatable string:
 *   const name = unsafeAsTranslated(user.displayName); // i18n-allow: BFF user data
 */
export function unsafeAsTranslated(s: string): TranslatedString {
  return s as TranslatedString;
}


